class FlowerCooler:
    def __init__(self):
        """Initialize the FlowerCooler with an empty dictionary to store batches."""
        self.batches = {}

    def add_batch(self, batch_id: str, freshness: int, days_left: int) -> None:
        """Add a new batch to the cooler with the given freshness and days left."""
        if not batch_id:
            raise ValueError("Batch ID cannot be empty")
        if not isinstance(freshness, int) or not (0 <= freshness <= 30):
            raise ValueError("Freshness must be an integer between 0 and 30")
        if not isinstance(days_left, int) or days_left < 0:
            raise ValueError("Days left must be a non-negative integer")
        if batch_id in self.batches:
            raise CoolerError(f"Batch ID '{batch_id}' already exists")
        self.batches[batch_id] = {'freshness': freshness, 'days_left': days_left}

    def remove_batch(self, batch_id: str) -> None:
        """Remove a batch from the cooler by its ID."""
        if batch_id not in self.batches:
            raise KeyError(f"Batch ID '{batch_id}' not found")
        del self.batches[batch_id]

    def end_day(self) -> None:
        """Update all batches at the end of the day."""
        for batch_id, batch in self.batches.items():
            if batch['days_left'] > 0:
                batch['freshness'] = max(0, batch['freshness'] - 2)
            else:
                batch['freshness'] = max(0, batch['freshness'] - 5)
            batch['days_left'] -= 1

    def get_freshness(self, batch_id: str) -> int:
        """Get the freshness of a batch by its ID."""
        if batch_id not in self.batches:
            raise KeyError(f"Batch ID '{batch_id}' not found")
        return self.batches[batch_id]['freshness']

    def get_days_left(self, batch_id: str) -> int:
        """Get the days left for a batch by its ID."""
        if batch_id not in self.batches:
            raise KeyError(f"Batch ID '{batch_id}' not found")
        return self.batches[batch_id]['days_left']

    def get_batches(self) -> list[str]:
        """Get a list of all batch IDs in the order they were added."""
        return list(self.batches.keys())

    def get_wilted(self) -> list[str]:
        """Get a list of wilted batch IDs (freshness is 0)."""
        return [batch_id for batch_id, batch in self.batches.items() if batch['freshness'] == 0]
