            raise AuctionError("Lot ID already exists")
        self.lots[lot_id] = {'opening_price': opening_price, 'highest_bid': None, 'current_bidder': None}

    def place_bid(self, lot_id: str, bidder: str, amount: int) -> None:
        """Place a bid on a lot."""
        if not lot_id in self.lots:
            raise KeyError("Lot ID not found")
        if not bidder or not isinstance(bidder, str):
            raise ValueError("Bidder must be a non-empty string")
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError("Bid amount must be a positive integer")
        if self.lots[lot_id]['current_bidder'] == bidder:
            raise AuctionError("Bidder already holds the highest bid")
        if self.lots[lot_id]['highest_bid'] is None:
            min_bid = self.lots[lot_id]['opening_price']
