        self.lots[lot_id]['current_bidder'] = bidder
        if lot_id not in self.bids:
            self.bids[lot_id] = []
        self.bids[lot_id].append((bidder, amount))

    def get_highest_bid(self, lot_id: str) -> tuple[str, int] | None:
        """Get the highest bid on a lot."""
        if not lot_id in self.lots:
            raise KeyError("Lot ID not found")
        return (self.lots[lot_id]['current_bidder'], self.lots[lot_id]['highest_bid']) if self.lots[lot_id]['highest_bid'] is not None else None

    def get_bids(self, lot_id: str) -> list[tuple[str, int]]:
        """Get all bids on a lot."""
        if not lot_id in self.lots:
            raise KeyError("Lot ID not found")
        return self.bids.get(lot_id, [])

    def get_leading_lots(self, bidder: str) -> list[str]:
        """Get the lots on which a bidder holds the highest bid."""
        return [lot_id for lot_id, info in self.lots.items() if info['current_bidder'] == bidder]

    def get_lots(self) -> list[str]:
        """Get all lot IDs."""
        return list(self.lots.keys())
