    pass


class Building:
    def __init__(self, top_floor: int):
        if top_floor < 1:
            raise ValueError("Top floor must be at least 1")
        self.top_floor = top_floor
        self.cars = {}
        self.waiting = [[] for _ in range(top_floor + 1)]
        self.delivered = []

    def add_car(self, car_id: str) -> None:
        if not car_id:
            raise ValueError("Car ID cannot be empty")
        if car_id in self.cars:
            raise ElevatorError("Car ID already exists")
        self.cars[car_id] = {"floor": 0, "riders": []}

    def call(self, passenger_id: str, floor: int) -> None:
        if not passenger_id:
            raise ValueError("Passenger ID cannot be empty")
        if floor < 0 or floor > self.top_floor:
            raise ValueError("Invalid floor")
        self.waiting[floor].append(passenger_id)

    def move_car(self, car_id: str, floor: int) -> None:
        if car_id not in self.cars:
            raise KeyError("Car ID not found")
        if floor < 0 or floor > self.top_floor:
            raise ValueError("Invalid floor")
        current_floor = self.cars[car_id]["floor"]
        if current_floor == floor:
            return

        # Get out the riders
        riders = self.cars[car_id]["riders"]
        self.delivered.extend(riders)
        self.cars[car_id]["riders"] = []

        # Get in the new passengers
        waiting = self.waiting[floor]
        new_riders = waiting[:4]
        self.waiting[floor] = waiting[4:]
        self.cars[car_id]["riders"] = new_riders

        self.cars[car_id]["floor"] = floor

    def get_car_floor(self, car_id: str) -> int:
        if car_id not in self.cars:
            raise KeyError("Car ID not found")
        return self.cars[car_id]["floor"]

    def get_riders(self, car_id: str) -> list[str]:
        if car_id not in self.cars:
            raise KeyError("Car ID not found")
        return self.cars[car_id]["riders"]

    def get_waiting(self, floor: int) -> list[str]:
        if floor < 0 or floor > self.top_floor:
            raise ValueError("Invalid floor")
        return self.waiting[floor]

    def get_delivered(self) -> list[str]:
        return self.delivered
