class ScoreboardError(Exception):
    pass


class Scoreboard:
    def __init__(self):
        self.teams = {}
        self.team_order = []

    def add_team(self, name: str) -> None:
        if not name:
            raise ValueError("Team name cannot be empty")
        if name in self.teams:
            raise ScoreboardError(f"Team '{name}' already exists")
        self.teams[name] = {'score': 0, 'events': []}
        self.team_order.append(name)

    def score(self, team: str, kind: str) -> None:
        if team not in self.teams:
            raise KeyError(f"Team '{team}' not found")
        if kind not in ["try", "conversion", "drop_goal"]:
            raise ValueError(f"Invalid kind '{kind}'")
        points = {'try': 5, 'conversion': 2, 'drop_goal': 3}[kind]
        self.teams[team]['score'] += points
        self.teams[team]['events'].append((kind, points))

    def get_score(self, team: str) -> int:
        if team not in self.teams:
            raise KeyError(f"Team '{team}' not found")
        return self.teams[team]['score']

    def get_events(self, team: str) -> list[tuple[str, int]]:
        if team not in self.teams:
            raise KeyError(f"Team '{team}' not found")
        return self.teams[team]['events']

    def get_standings(self) -> list[str]:
        return sorted(self.team_order, key=lambda t: self.teams[t]['score'], reverse=True)

    def get_teams(self) -> list[str]:
        return self.team_order
