            raise ValueError("Empty coach id")
        if seats <= 0:
            raise ValueError("Number of seats must be greater than 0")
        if coach_id in self.coaches:
            raise ReservationError(f"Coach {coach_id} already added")
        self.coaches[coach_id] = {
            'seats': seats,
            'limit': seats * 7 // 10,
            'reserved': 0
        }

