                    self.projects[project].append((id, title, due_day, done))
                    return
        raise KeyError(f"Task ID {task_id} not found")

    def get_task(self, task_id: int) -> tuple[str, int]:
        if not isinstance(task_id, int):
            raise KeyError("Invalid task ID")
        for project, tasks in self.projects.items():
            for id, title, due_day, done in tasks:
                if id == task_id:
